/** newest builtin provider config on disk */
function builtinConfig() {
  const base = join(HOME, '.zcode', 'v2', 'runtime', 'provider', 'windows-x86_64');
  let versions = [];
  try { versions = readdirSync(base).sort().reverse(); } catch { return null; }
  for (const v of versions) {
    const vdir = join(base, v);
    let endpoints = [];
    try { endpoints = readdirSync(vdir).filter((e) => e.startsWith('endpoint-')); } catch { continue; }
    for (const e of endpoints) {
      const f = join(vdir, e, 'zcode-builtin.json');
      if (existsSync(f)) return f;
    }
  }
  return null;
}

const personal = join(HOME, '.zcode', 'v2', 'provider_config.json');
const clean = { ...process.env };
for (const k of Object.keys(clean)) if (k.startsWith('ZCODE_')) delete clean[k];

const variants = [
  ['no ZCODE_*', {}],
  ['+builtin only', { ZCODE_BUILTIN_PROVIDER_CONFIG_FILE: builtinConfig() }],
  ['+builtin+personal', { ZCODE_BUILTIN_PROVIDER_CONFIG_FILE: builtinConfig(), ZCODE_PERSONAL_PROVIDER_CONFIG_FILE: personal }],
  ['+builtin+personal+appversion', { ZCODE_BUILTIN_PROVIDER_CONFIG_FILE: builtinConfig(), ZCODE_PERSONAL_PROVIDER_CONFIG_FILE: personal, ZCODE_APP_VERSION: '3.14.3' }],
  ['all discovered', {
    ZCODE_BUILTIN_PROVIDER_CONFIG_FILE: builtinConfig(),
    ZCODE_PERSONAL_PROVIDER_CONFIG_FILE: personal,
    ZCODE_APP_VERSION: '3.14.3',
    ZCODE_BASE_URL: 'https://zcode.z.ai',
    ZCODE_ENV: 'production',
    ZCODE_RUNTIME_ENV: 'production',
    ZCODE_WINDOWS_APP_INSTALL_DIR: 'C:\\Users\\UserX\\AppData\\Local\\Programs\\ZCode',
  }],
];

const probe = (label, extra) => new Promise((resolve) => {
  const child = spawn(NODE, [ZCODE, '-p', 'Reply with exactly: ENV_PROBE_OK', '--json', '--cwd', process.cwd()],
    { env: { ...clean, ...extra }, cwd: process.cwd(), windowsHide: true });
  let out = '';
  child.stdout.on('data', (d) => { out += d; });
  child.stderr.on('data', (d) => { out += d; });
  const t = setTimeout(() => { child.kill(); resolve(`${label}: TIMEOUT`); }, 120000);
  child.on('close', (code) => {
    clearTimeout(t);
    const ok = /ENV_PROBE_OK/.test(out);
    const why = out.split(/\r?\n/).filter((l) => /error|Error|无法|Failed/.test(l)).slice(0, 2).join(' ');
    resolve(`${label}: exit=${code} ${ok ? 'OK' : 'FAIL'} ${ok ? '' : why.slice(0, 220)}`);
  });
});

