    <div class="sw"></div>
    <div class="role">舞女</div>
    <div class="name">游戏好友A</div>
  </div>
  <script type="module">
    window.film = { duration: 2.5, frame(t) {
      const y1 = 120, y2 = 860;
      const p = Math.min(1, t / 0.6);
      const ease = 1 - Math.pow(1 - p, 3);
      const b1 = document.querySelector('.bar'), b2 = document.querySelector('.bar2');
      b1.style.opacity = ease; b2.style.opacity = ease;
      b1.style.transform = `translateX(${(1 - ease) * -80}px)`;
      b2.style.transform = `translateX(${(1 - ease) * -80}px)`;
      if (t > 2.1) {
        const o = Math.max(0, 1 - (t - 2.1) / 0.4);
        b1.style.opacity = o; b2.style.opacity = o;
      }
    } };
  </script>
</body>
</html>
