{"content": "#!/usr/bin/env node
/**
 * assemble.mjs — 从 cutlist.json 生成 OpenFilm 工程：
 *   1. 每个片段用 ffmpeg 转码（模糊填充 1920x1080，慢动作段用 90fps 源做丝滑减速）
 *   2. 生成字幕页 pages/cap_XX.html（静态确定性）
 *   3. 生成 film.html（轨道：文字特效 / 暗角 / 视频 / 音乐）
 *
 * 用法：node assemble.mjs [cutlist 路径]
 */
import { spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { basename, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));      // 剪辑/work
const ROOT = resolve(HERE, '..');                          // 剪辑/
const PROJECT = process.argv[3] || join(ROOT, '今夜奔向你');
const CUTLIST = process.argv[2] || join(HERE, 'cutlist.json');
const FFMPEG = 'C:\\Users\\UserX\\AppData\\Local\\Programs\\OpenFilm\\resources\\runtime\\ffmpeg\\ffmpeg.exe';

const cfg = JSON.parse(readFileSync(CUTLIST, 'utf8'));
const ASSETS = join(PROJECT, 'assets');
const PAGES = join(PROJECT, 'pages');
mkdirSync(ASSETS, { recursive: true });
mkdirSync(PAGES, { recursive: true });

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const fmt = (n) => Number(n.toFixed(3)).toString();

/* ── 1. 转码片段 ───────────────────────────────────────────── */
console.log('== transcode clips ==');
for (const c of cfg.segments) {
  const out = join(ASSETS, c.file);
  if (existsSync(out) && !process.env.FORCE) { console.log('  skip', c.file); continue; }
  const speed = c.speed ?? 1;
  // 90fps 源：慢动作也丝滑。模糊填充保 HUD。
  const vf = speed === 1
    ? 'fps=30,split=2[bg][fg];[bg]scale=1920:1080:flags=lanczos,boxblur=20:2,eq=brightness=-0.07[bgb];[fg]scale=1920:860:flags=lanczos[fgs];[bgb][fgs]overlay=0:110,format=yuv420p'
    : `[0:v]setpts=${1 / speed}*PTS,fps=30,split=2[bg][fg];[bg]scale=1920:1080:flags=lanczos,boxblur=20:2,eq=brightness=-0.07[bgb];[fg]scale=1920:860:flags=lanczos[fgs];[bgb][fgs]overlay=0:110,format=yuv420p`;
  const args = ['-ss', String(c.in), '-i', join(ROOT, '原始素材.mp4'), '-t', String((c.out - c.in) * (speed === 1 ? 1 : 1)), '-vf', vf, '-an', '-c:v', 'libx264', '-crf', '18', '-preset', 'medium', '-y', out];
  const r = spawnSync(FFMPEG, args, { stdio: ['ignore', 'ignore', 'pipe'] });
  if (r.status !== 0) { console.error('FFMPEG FAIL', c.file, String(r.stderr).slice(-400)); process.exit(1); }
  console.log('  ok', c.file, `${(c.out - c.in).toFixed(1)}s src, speed ${speed}x`);
}

/* ── 2. 字幕页 ─────────────────────────────────────────────── */
console.log('== subtitle pages ==');
const CAP_TPL = (text, hl) => `<!doctype html>
<html><head><meta charset="utf-8"><style>
  html, body { margin: 0; width: 1920px; height: 1080px; overflow: hidden; }
  .cap { position: absolute; left: 0; right: 0; bottom: 96px; text-align: center;
    color: #fff; font: 900 62px/1.25 "Noto Sans SC", "Microsoft YaHei", sans-serif;
    letter-spacing: .03em; padding: 0 120px;
    text-shadow: -4px -4px 0 #000, 4px -4px 0 #000, -4px 4px 0 #000, 4px 4px 0 #000, 0 8px 24px rgba(0,0,0,.65); }
  .hl { color: #ffb648; }
</style></head><body><div class="cap">${text}</div>
<script type="module">window.film = { duration: __DUR__, frame(t) {} };</script></body></html>
`;
for (const c of cfg.caps) {
  const file = join(PAGES, `${c.page}.html`);
  const body = esc(c.text).replace(/\[\[(.+?)\]\]/g, '<span class="hl">$1</span>');
  writeFileSync(file, CAP_TPL(body).replace('__DUR__', fmt(c.dur ?? 2)));
}
console.log('  caps:', cfg.caps.length);

/* ── 3. film.html ──────────────────────────────────────────── */
console.log('== film.html ==');
let t = 0;
const fx = [], vids = [], auds = [];
for (const c of cfg.segments) {
  const dur = (c.out - c.in) / (c.speed ?? 1);
  vids.push(`  <video src="assets/${c.file}" at="${fmt(t)}"${(c.speed ?? 1) !== 1 ? ` speed="${c.speed}"` : ''}></video>`);
  if (c.cap) {
    fx.push(`  <iframe src="pages/${c.cap}.html" at="${fmt(t + (c.capOffset ?? 0))}" style="width:1920px; height:1080px" duration="${fmt(c.capDur ?? Math.min(dur, 3))}"></iframe>`);
  }
  if (c.flash) fx.push(`  <iframe src="pages/flash.html" at="${fmt(t - 0.1)}" style="width:1920px; height:1080px"></iframe>`);
  t += dur;
}
const total = t;
for (const m of cfg.music) {
  auds.push(`  <audio src="assets/${m.file}" at="${fmt(m.at)}"${m.in != null ? `#t=${fmt(m.in)},${fmt(m.out)}` : ''} volume="${m.volume ?? 0.9}"></audio>`.replace(' at="0"#', '#').replace(/" at="0" /, ' ').replace(/audio src="([^"]+)" at="0"/, 'audio src="$1"'));
}
const filmHtml = `<!doctype html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=1920, height=1080">
<style>
  html, body { margin: 0; height: 100%; background: #000; }
  iframe { border: 0; }
  video { filter: saturate(1.12) contrast(1.06); }
</style>
</head>
<body>
<section>
${fx.join('\n')}
</section>
<section>
  <iframe src="pages/vignette.html" at="0" style="width:1920px; height:1080px"></iframe>
</section>
<section>
${vids.join('\n')}
</section>
<section>
${auds.join('\n')}
</section>
</body>
</html>
`;
writeFileSync(join(PROJECT, 'film.html'), filmHtml);
console.log(`  total ${fmt(total)}s, ${cfg.segments.length} clips, ${cfg.caps.length} caps, ${cfg.music.length} tracks`);
", "file_path": "C:\Users\UserX\Downloads\剪辑\work\assemble.mjs"}

