def energy1s(path, lo, hi):
    d, sr = sf.read(path)
    if d.ndim > 1: d = d.mean(1)
    d = d.astype(np.float32)
    sec = sr
    out = []
    for i in range(lo, min(hi, len(d)//sec)):
        seg = d[i*sec:(i+1)*sec]
        out.append(round(float(np.sqrt((seg**2).mean())), 3))
    return out

