// 用法: node work/v4/state.mjs
import { spawnSync } from 'node:child_process';
import { mkdirSync, writeFileSync } from 'node:fs';

const FF = 'C:/Users/UserX/AppData/Local/Programs/OpenFilm/resources/runtime/ffmpeg/ffmpeg.exe';
const SRC = '原始素材.mp4';
const DIR = 'work/v4/raw';
mkdirSync(DIR, { recursive: true });

const BOXES = {
  doc: { x: 1132, y: 68 },
  dan: { x: 1266, y: 68 },
  exe: { x: 1400, y: 68 },
};
const W = 48, H = 48;

for (const [name, b] of Object.entries(BOXES)) {
  const out = `${DIR}/${name}.raw`;
  const r = spawnSync(FF, ['-v', 'error', '-i', SRC, '-vf', `fps=1,crop=${W}:${H}:${b.x}:${b.y}`, '-f', 'rawvideo', '-pix_fmt', 'rgb24', '-y', out]);
  if (r.status !== 0) throw new Error(String(r.stderr));
}

function analyze(name) {
  const fs = require('node:fs');
}

import { readFileSync } from 'node:fs';
const stride = W * H * 3;

const series = {};
for (const name of Object.keys(BOXES)) {
  const buf = readFileSync(`${DIR}/${name}.raw`);
  const n = Math.floor(buf.length / stride);
  const rows = [];
  for (let f = 0; f < n; f++) {
    const base = f * stride;
    // 1) 红横条：中间若干行里红色像素占整行比例
    let bestRedRow = 0, bestRowIdx = -1;
    for (let y = 12; y < H - 12; y++) {
      let red = 0;
      for (let x = 4; x < W - 4; x++) {
        const i = base + (y * W + x) * 3;
        const r = buf[i], g = buf[i + 1], b = buf[i + 2];
        if (r > 140 && g < 95 && b < 95 && r - g > 60 && r - b > 50) red++;
      }
      const frac = red / (W - 8);
      if (frac > bestRedRow) { bestRedRow = frac; bestRowIdx = y; }
    }
    // 2) 整体饱和度与亮度（判断灰白剪影）
    let satSum = 0, lumSum = 0, cnt = 0, redPix = 0;
    for (let y = 6; y < H - 6; y += 2) {
      for (let x = 6; x < W - 6; x += 2) {
        const i = base + (y * W + x) * 3;
        const r = buf[i], g = buf[i + 1], b = buf[i + 2];
        const mx = Math.max(r, g, b), mn = Math.min(r, g, b);
        satSum += (mx - mn) / (mx || 1);
        lumSum += (r * 0.299 + g * 0.587 + b * 0.114);
        if (r > 140 && g < 95 && b < 95) redPix++;
        cnt++;
      }
    }
    rows.push({
      t: f,
      redRow: +bestRedRow.toFixed(2),
      redRowY: bestRowIdx,
      sat: +(satSum / cnt).toFixed(3),
      lum: Math.round(lumSum / cnt),
      redFrac: +(redPix / cnt).toFixed(3),
    });
  }
  series[name] = rows;
}

writeFileSync('work/v4/state.json', JSON.stringify(series, null, 0));
console.log('frames', Object.fromEntries(Object.entries(series).map(([k, v]) => [k, v.length])));

// 打印「疑似被挂」区间（红条 >=0.55）
for (const name of Object.keys(series)) {
  const rows = series[name];
  const hits = rows.filter((r) => r.redRow >= 0.55);
  const runs = [];
  let cur = null;
  for (const h of hits) {
    if (cur && h.t - cur.end <= 2) cur.end = h.t;
    else { cur = { start: h.t, end: h.t }; runs.push(cur); }
  }
  console.log(name, 'redbar runs:', runs.map((r) => `${r.start}-${r.end}`).join(', ') || 'none');
}
